<!doctype html><html lang="ru"><head><meta charset="utf-8"><title>Журнал посещаемости</title><style>@page{size:A4 landscape;margin:10mm}body{font-family:Arial,sans-serif;font-size:11px}h1{text-align:center;font-size:18px}.meta{text-align:center;margin-bottom:10px}table{border-collapse:collapse;width:100%}th,td{border:1px solid #555;padding:4px;text-align:center}th.name,td.name{text-align:left;min-width:180px}.no-print{margin-bottom:10px}@media print{.no-print{display:none}}</style></head><body><button class="no-print" onclick="window.print()">Печать</button><h1>Журнал посещаемости</h1><div class="meta">{{request('program_id')?'Программа #'.request('program_id'):'Все программы'}} {{request('group_id')?'· группа #'.request('group_id'):''}}</div><table><thead><tr><th>№</th><th class="name">ФИО</th>@foreach($dates as $d)<th>{{CarbonCarbon::parse($d)->format('d.m')}}</th>@endforeach<th>Посещено</th><th>Пропущено</th></tr></thead><tbody>@foreach($enrollments as $i=>$e)@php($p=0)@php($a=0)<tr><td>{{$i+1}}</td><td class="name">{{$e->user?->full_name}}</td>@foreach($dates as $d)@php($m=$matrix->get($e->id.'-'.$d))@php($p+=in_array($m?->status,['present','late'])?1:0)@php($a+=in_array($m?->status,['absent','excused'])?1:0)<td>{{match($m?->status){'present'=>'Я','absent'=>'Н','excused'=>'У','late'=>'О',default=>'—' }}}</td>@endforeach<td>{{$p}}</td><td>{{$a}}</td></tr>@endforeach</tbody></table><p>Я — присутствовал, Н — отсутствовал, У — уважительная причина, О — опоздание.</p></body></html>